UPDATE na_sensitive_access_alert alert SET alert_status = 'Suppressed', suppressed_by = #{operator}, suppressed_time = CURRENT_TIMESTAMP, suppressed_reason = #{suppressedReason}, suppressed_requested_by = #{suppressedRequestedBy}, update_by = #{operator}, update_time = CURRENT_TIMESTAMP WHERE alert.id = #{id} AND alert.alert_status = 'Pending'
AND alert.cmdb_id IN
#{cmdbId}

UPDATE na_sensitive_access_alert
SET last_send_time = #{sendTime}
WHERE id = #{id}
  AND alert_status = 'Pending'
